import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"From Slow Bidirectional to Fast Autoregressive Video Diffusion Models","description":"","frontmatter":{"title":"From Slow Bidirectional to Fast Autoregressive Video Diffusion Models","arxiv":"2412.07772","date":"2024-12-10","authors":"Tianwei Yin, Qiang Zhang, Richard Zhang, William T. Freeman, Frédo Durand, Eli Shechtman, Xun Huang","categories":"cs.CV","topics":"自回归视频生成, 分布匹配蒸馏, 流式生成","outline":[2,2]},"headers":[],"relativePath":"papers/2412.07772.md","filePath":"papers/2412.07772.md","lastUpdated":null}'),l={name:"papers/2412.07772.md"};function e(i,s,r,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="from-slow-bidirectional-to-fast-autoregressive-video-diffusion-models" tabindex="-1">From Slow Bidirectional to Fast Autoregressive Video Diffusion Models <a class="header-anchor" href="#from-slow-bidirectional-to-fast-autoregressive-video-diffusion-models" aria-label="Permalink to &quot;From Slow Bidirectional to Fast Autoregressive Video Diffusion Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2412.07772" target="_blank" rel="noreferrer">2412.07772</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-12-10</td></tr><tr><td><strong>作者</strong></td><td>Tianwei Yin, Qiang Zhang, Richard Zhang, William T. Freeman, Frédo Durand, Eli Shechtman, Xun Huang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用<strong>双向教师</strong>去蒸馏一个<strong>因果学生</strong>（非对称蒸馏），再配上教师 ODE 轨迹回归的初始化，把 50 步双向视频扩散压成 4 步、块因果、带 KV cache 的自回归生成器，首帧延迟从 219 秒降到 1.3 秒。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/autoregressive">自回归视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文按 <strong>v4</strong>（2025-09-23 修订，CVPR 2025）全文撰写，v1 提交于 2024-12-10，frontmatter 日期取首次提交日。本站论文索引里的 &quot;CausVid&quot; 是论文中的模型名，arXiv 正式标题为 <em>From Slow Bidirectional to Fast Autoregressive Video Diffusion Models</em>，非编号错误。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>主流视频扩散模型用双向注意力一次性对整段视频去噪。这个设计有两个后果：<strong>生成任何一帧都需要处理整段序列（包括未来）</strong>，因此第一帧要等到全部去噪结束才能看到；以及计算与显存随帧数二次增长。论文给的数字很直白——他们的双向教师生成一段 10 秒 120 帧的视频要 <strong>219.2 秒</strong>，吞吐 0.6 FPS。对交互式应用来说这是致命的：用户输入随时可能变，而模型在算当前帧时依赖的是尚不存在的未来条件。</p><p>自回归模型天然解决延迟问题，但当时的自回归视频模型有两个老毛病：误差累积（每一帧都建立在可能有瑕疵的前几帧上，偏差被逐步放大），以及速度仍然远达不到交互帧率。论文要同时解决这三件事——因果性、速度、以及因果化带来的质量损失。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>双向视频扩散</strong>（Sora、MovieGen、CogVideoX 一系）质量最好，但结构性地不支持流式。<strong>离散 token 自回归</strong>（VideoGPT、VideoPoet 一系）因果性天然，但每帧要生成数千个 token，且矢量量化有损，画质上不去。<strong>扩散-自回归混合</strong>在 2024 年已经出现不少（Diffusion Forcing、AR-Diffusion、CA2 等），但它们通常要么保留多步去噪（慢），要么在长 rollout 中掉质量。</p><p>论文最关键的一处&quot;前人不足&quot;诊断是关于<strong>蒸馏路线本身</strong>的。直觉上想要一个快的因果模型，应该先把双向 DiT 微调成因果 DiT（当教师），再蒸馏成少步学生。作者的初期实验说明这条路走不通，原因有两层：一是因果扩散模型本身就弱于双向对应物（表 4：多步因果 92.4/60.1/28.5 vs 多步双向 94.6/62.7/29.6），学生受限于更弱的教师；二是误差累积这个问题会<strong>从教师传染给学生</strong>——教师本身在长 rollout 中就会退化，学生只会学到这份退化。</p><p>DMD（Distribution Matching Distillation）当时只在图像扩散上验证过，把它搬到视频上、并且让教师与学生的注意力结构不一致，是本文要处理的新问题。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>只用 2024 年底之前的已有材料，可以这样一步步走到非对称蒸馏。</p><p>第一步是承认一个经验事实：因果化会掉质量。既然如此，就不要让因果模型承担&quot;提供监督信号&quot;的角色。</p><p>第二步是注意到 DMD 的一个结构性质：它匹配的是<strong>分布</strong>，而不是逐样本的输出。DMD 的梯度来自&quot;真实分数网络&quot;与&quot;学生分数网络&quot;之差，真实分数由预训练教师近似。既然教师只被当作一个分数函数来用、只需要对<strong>加噪后的样本</strong>给出分数，那么教师的架构是否因果，与学生的架构是否因果，在数学上并不需要一致。这是&quot;非对称&quot;这个想法的合法性来源。</p><p>第三步是问：非对称有没有额外好处？有。双向教师从未经历过自回归 rollout，因此它的分数函数里不含误差累积的痕迹；用它当监督，学生被推向的是一个&quot;没有累积误差&quot;的目标分布。作者据此声称非对称蒸馏显著减轻了误差累积。</p><p>第四步是稳定性。直接对一个刚换了注意力掩码的模型上 DMD 损失会不稳（架构差异太大）。既然教师能跑 ODE 采样，那就先造一小批 ODE 轨迹对，用回归损失把学生&quot;拉到&quot;教师的少步轨迹附近再开始 DMD。这是一个便宜的初始化技巧，而不是训练主体。</p><p>第五步是工程：块内双向、块间因果的注意力掩码，配 3D VAE 的 chunk 结构；推理时因为有 KV cache，掩码根本不需要，可以直接用最快的双向注意力核。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>想要一个快的因果视频生成器，不要去找一个因果老师。因果老师本身就带着误差累积和质量损失，学生只会继承这些毛病。DMD 只需要教师提供&quot;真实分布在加噪空间里的分数&quot;，这件事与教师能否流式无关——所以让<strong>最强的双向模型当老师、让因果模型当学生</strong>，用分布匹配把结构差异跨过去。速度则由少步蒸馏（50 步 → 4 步）和 KV cache 一并解决。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以生成一段 10 秒、120 帧的视频为例。</p><ol><li><strong>潜空间与分块</strong>。3D VAE 把若干原始帧编码成一个 latent chunk。学生每个 chunk 含 <strong>5 个 latent 帧</strong>，逐 chunk 生成。</li><li><strong>块因果架构</strong>。学生与教师架构完全相同，唯一差别是注意力掩码：chunk 内部保持双向自注意力以捕捉局部时序依赖，chunk 之间用因果注意力禁止看未来。形式上掩码由 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">⌊</span><span class="mord mathnormal">i</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mclose">⌋</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">⌊</span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mclose">⌋</span></span></span></span> 这类条件给出（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 为 chunk 大小）。作者指出这<strong>不比全因果更慢</strong>——因为 VAE 解码器本来就需要凑齐一整块 latent 才能出像素。训练用 FlexAttention 实现该掩码。</li><li><strong>阶段一：ODE 初始化</strong>。用双向教师采 <strong>1000 组</strong> ODE 轨迹对：先采噪声，再用 ODE solver 模拟反向扩散得到整条轨迹，从中挑出与学生 4 步调度对应的那几个时间点。学生（由教师权重初始化）在这些对上做回归。这一步计算量很小，目的只是稳定后续训练。</li><li><strong>阶段二：非对称 DMD</strong>（算法 1）。每次迭代：从数据集采一段视频切成 chunk；<strong>为每个 chunk 独立采样时间步</strong>并加噪；学生在块因果掩码下一次性预测所有 chunk 的干净帧；再采一个统一时间步对预测结果加噪；用 DMD 损失更新学生；同时用标准去噪损失更新&quot;学生分布的分数网络&quot;。采用 DMD2 的双时间尺度更新规则。</li><li><strong>推理</strong>（算法 2）。逐 chunk 生成：初始化当前 chunk 为噪声，做 4 步去噪（每步都用已有 KV cache），完成后前向一次算出该 chunk 的 KV 并追加进 cache。因为有 cache，块因果掩码在推理时不再需要，可以直接调用最快的双向注意力实现。</li><li><strong>零样本衍生任务</strong>。图生视频：把输入图复制成第一个 chunk，然后自回归续写，无需任何额外训练。流式视频到视频翻译：仿 SDEdit，对每个输入 chunk 注入某个时间步的噪声再一步去噪。动态 prompt：任意时刻换文本条件继续生成。</li></ol><p><strong>训练规模</strong>：约 40 万条有完整版权的内部单镜头视频（图像与视频混合，遵循 CogVideoX 的配方），全流程约 <strong>2 天 × 64 张 H100</strong>。教师在 10 秒、12 FPS 上训练。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p><strong>块因果掩码</strong>。设 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">i</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span></span></span></span> 为帧索引、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span></span></span></span> 为 chunk 大小，注意力掩码允许 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span></span></span></span> 被 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 看到当且仅当二者同块或 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span></span></span></span> 在更早的块：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">ij</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord">1</span><span class="mord"><span class="delimsizing size2">[</span></span><span class="mord"><span class="delimsizing size1">⌊</span></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord"><span class="delimsizing size1">⌋</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord"><span class="delimsizing size1">⌊</span></span><span class="mord mathnormal">i</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mord"><span class="delimsizing size1">⌋</span></span><span class="mord"><span class="delimsizing size2">]</span></span><span class="mord">.</span></span></span></span></span></p><p>这比全因果掩码宽松（块内可以互看未来），但不增加延迟，因为 VAE 解码本来就以块为单位。</p><p><strong>DMD 的核心</strong>。要让学生分布 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 逼近数据分布 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">data</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，DMD 最小化二者在加噪空间上的反向 KL。其梯度可写成两个分数函数之差：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">KL</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∥</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">data</span></span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∝</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord mathbb">E</span><span class="mord"><span class="delimsizing size2">[</span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">fake</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.0574em;vertical-align:-0.686em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">real</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord" style="margin-right:0.0556em;">∂</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord"><span class="delimsizing size2">]</span></span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">real</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 由<strong>预训练教师</strong>近似，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">fake</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 由一个随学生一起在线训练的 critic 网络给出。</p><p>这里是理解全文的关键：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">real</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是一个<strong>只依赖于输入样本与噪声水平</strong>的函数。它接收一段加了噪的视频，输出该点处指向数据流形的方向。这个函数<strong>不关心生成这段视频的过程是不是因果的</strong>。因此&quot;教师双向、学生因果&quot;在数学上没有任何冲突——教师从来不需要模拟学生的采样过程，它只需要在学生的输出上评分。这就是非对称蒸馏能成立的全部理由。</p><p>反过来，这也解释了它的代价：反向 KL 是<strong>寻峰的（mode-seeking）</strong>。它惩罚&quot;学生在数据没有支撑的地方放置概率质量&quot;，但不惩罚&quot;学生漏掉数据的某些模式&quot;。因此学生会倾向于集中到高密度区域，表现为<strong>更锐利、更干净但更缺乏多样性</strong>的输出。作者在讨论里明确承认了这一点。</p><p><strong>ODE 初始化</strong>。学生先在教师的 ODE 轨迹对上做回归：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ODE</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathbb">E</span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mopen">∥</span><span class="mord"><span class="mord mathnormal">G</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2819em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3473em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.3434em;vertical-align:-0.4443em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2819em;"><span></span></span></span></span></span></span></span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">teacher</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4443em;"><span></span></span></span></span></span></span><span class="mclose"><span class="mclose">∥</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">]</span></span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9012em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 取自学生的 4 步调度。这只是把学生放到教师少步轨迹的邻域里，不是最终目标。表 4 显示它单独使用几乎没用（见 §7）。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>评测协议</strong>。主结果用 MovieGen 的前 128 条 prompt 生成视频，按 VBench 竞赛评测套件的三个维度打分：Temporal Quality / Frame Quality / Text Alignment。全量 VBench 结果放在附录。速度在单张 H100 上测。</p><p><strong>问题一：因果 + 少步之后，质量还剩多少？</strong> 表 1（约 10 秒短视频）：CausVid 94.7 / 64.4 / 30.1，三项全面高于 CogVideoX-5B（89.9/59.8/29.1）、OpenSORA（88.4/52.0/28.4）、Pyramid Flow（89.6/55.9/27.1）与 MovieGen（91.5/61.1/28.8）。附录里 VBench-Long 总分 <strong>84.27</strong>，作者称当时在所有官方评测过的模型中排第一。</p><p><strong>问题二：长视频是否会退化？</strong> 表 2（约 30 秒，滑窗推理、用上一段末尾帧作为下一段上下文）：CausVid 94.9/63.4/28.9，时序与画质均为最好；文本对齐 28.9 略低于 FIFO-Diffusion 的 29.9，作者的措辞是&quot;competitive&quot;。图 8 画出 30 秒内画质随时间的曲线，作者称 CausVid 与 FIFO-Diffusion 最能保持画质，而多步因果基线（橙色）明显退化并把退化传给了从它蒸馏出的学生（绿色）。<strong>这条主证据只有曲线，论文没有给出对应的数值表。</strong></p><p><strong>问题三：延迟与吞吐提升多少？</strong> 表 3（10 秒 120 帧，含文本编码器、扩散模型与 VAE 解码的总时间）：双向教师 219.2 秒 / 0.6 FPS；CogVideoX-5B 208.6 秒 / 0.6 FPS；Pyramid Flow 6.7 秒 / 2.5 FPS；CausVid <strong>1.3 秒 / 9.4 FPS</strong>。</p><p><strong>问题四：非对称到底贡献了什么？（表 4，核心消融）</strong></p><ul><li>多步双向（100 次前向）：94.6 / 62.7 / 29.6</li><li>多步因果（100 次前向）：92.4 / 60.1 / 28.5 —— 因果化本身的代价</li><li>4 步，无 ODE 初始化 + 双向教师：93.4 / 60.6 / 29.4</li><li>4 步，有 ODE 初始化 + <strong>无教师</strong>（纯 ODE 回归）：92.9 / <strong>48.1</strong> / 25.3</li><li>4 步，有 ODE 初始化 + <strong>因果</strong>教师：91.9 / 61.7 / 28.2</li><li>4 步，有 ODE 初始化 + <strong>双向</strong>教师（最终配置）：<strong>94.7 / 64.4 / 30.1</strong></li></ul><p>三条结论可以直接读出来。第一，纯 ODE 初始化的画质只有 48.1，远低于任何带教师的配置——<strong>画质增益几乎全部来自 DMD</strong>，ODE 初始化只是稳定器。第二，把教师从因果换成双向，三项分别 +2.8 / +2.7 / +1.9，这是&quot;非对称&quot;这一核心 claim 的直接证据。第三，ODE 初始化在有双向教师时贡献 +1.3 / +3.8 / +0.7。</p><p><strong>问题五：人类怎么看？</strong> 从 MovieGenBench 取前 29 条 prompt，在 Prolific 上每个模型对每条 prompt 收 3 份评分，共 <strong>87 份/模型对</strong>，固定随机种子 0。结论：CausVid 相对 MovieGen、CogVideoX、Pyramid Flow 一致占优，且与其双向教师相当。</p><p><strong>问题六：能否零样本迁移到别的任务？</strong> 流式视频翻译（DAVIS 的 67 条里取 60 条帧数 ≥16 的）：CausVid 93.2/61.7/27.7 优于 StreamV2V 的 92.5/59.3/26.9。图生视频（VBench-I2V，零样本）：CausVid 92.0/65.0/28.9，时序质量明显高于 CogVideoX-5B 的 87.0 与 Pyramid Flow 的 88.4。另展示了一段 14 分钟的生成视频，作者称&quot;轻微过曝但整体质量保持&quot;。</p><p><strong>作者自陈的代价</strong>：学生在逐帧画质上超过双向教师，但在<strong>时序闪烁与输出多样性上更差</strong>。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：因果视频扩散模型天生弱于双向对应物，所以不要用因果模型当蒸馏教师——它会把自己的质量损失和误差累积一起传给学生。DMD 只需要教师提供加噪空间里的分数函数，这与教师是否因果无关，因此可以做&quot;双向教师 → 因果学生&quot;的非对称蒸馏。再配上用教师 ODE 轨迹对做回归的初始化来稳住训练，50 步双向模型可以压成 4 步块因果生成器。结果是首帧延迟 219.2 秒降到 1.3 秒、吞吐 0.6 FPS 升到 9.4 FPS，而三项质量指标全面超过自己的多步双向教师。代价是反向 KL 的寻峰性导致多样性下降，且时序闪烁比教师更明显。</p><p><strong>3 句话版</strong>：教师的架构约束与学生的架构约束可以解耦，因为分布匹配只在样本空间里比较。这一解耦同时买到了速度（少步）、因果性（流式）和抗误差累积（教师没见过 rollout）。但反向 KL 的模式坍缩是这套方案的固有税。</p><p><strong>1 句话版</strong>：非对称蒸馏证明了&quot;想要因果学生，未必需要因果教师&quot;，这条思路后来成了实时视频生成的默认起点。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p><strong>假设：训练时学生在&quot;带噪真实上下文&quot;下产生的输出分布，可以代表它在推理时&quot;自生成上下文&quot;下的分布。</strong></p><p>看算法 1 的第 5–8 行就能定位这个问题：训练时从<strong>数据集</strong>采一段真实视频、切成 chunk、给每个 chunk 独立采时间步加噪，然后学生在块因果掩码下<strong>并行</strong>预测所有 chunk。这是 Diffusion Forcing 式的输入构造。但推理时（算法 2）学生是<strong>串行</strong>的，每个 chunk 的上下文是它自己前面几步生成的、完全干净的输出。</p><p>这两个分布并不相同。DMD 损失衡量的是&quot;学生在训练输入下的输出分布&quot;与&quot;数据分布&quot;的差距，而我们真正关心的是&quot;学生在推理条件下的输出分布&quot;与数据分布的差距。如果这个假设不成立，那么优化目标本身就对错了对象——这不是精度问题，是靶心问题。</p><p>论文为该假设提供的间接证据是图 8 的画质保持曲线和 14 分钟的长视频样例。但这两者都不能排除&quot;分布错配仍然存在、只是被非对称教师部分掩盖了&quot;。</p><p><strong>文献已有结论</strong>（非本文声明）：同期的 Self Forcing（<a href="https://arxiv.org/abs/2506.08009" target="_blank" rel="noreferrer">2506.08009</a>，Xun Huang 是两篇的共同作者）明确把这一点指认为 CausVid 的核心缺陷——&quot;CausVid 训练时的输出（由 Diffusion Forcing 生成）不来自模型推理时产生的分布，因此 DMD 损失在匹配错误的分布&quot;。Self Forcing 在自己的实现框架下把 DF+DMD（即在同一设定下复现的 CausVid）与 Self Forcing 直接对比，chunk-wise 设定下 82.76 vs 84.31，frame-wise 设定下差距更大（80.56 vs 84.26）。也就是说，这个&quot;最脆弱的假设&quot;在约一年半后被同一作者线的后续工作以实验证伪，且证伪的幅度在帧级自回归下相当可观。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>目标：不复现 2 天 × 64 卡的训练，只验证&quot;教师架构不对称&quot;是否真的是增益来源。</p><ul><li><strong>数据与模型</strong>：用任何一个开源的双向视频扩散骨干（比如 Wan2.1-T2V-1.3B 或 CogVideoX-2B）与其公开权重。视频数据只需要一个几万条量级的公开集，因为消融关心的是相对差异而非绝对 SOTA。</li><li><strong>实现</strong>：固定学生架构（块因果、chunk=5 latent 帧、4 步），固定 ODE 初始化配方（1000 组轨迹对），只切换 DMD 里的 real score 网络：(A) 原始双向骨干；(B) 把同一骨干先用去噪损失微调成块因果模型再当教师。两条支线的训练步数、学习率、guidance scale、DMD2 更新比例完全一致。</li><li><strong>测量</strong>：在同一组 128 条 prompt 上算 VBench 竞赛套件三项；额外记录 (i) 30 秒滑窗 rollout 下画质随帧数的曲线；(ii) 输出多样性——同 prompt 换 8 个种子，算两两之间的特征距离均值。</li><li><strong>判据</strong>：若 (A) 相对 (B) 在三项上的优势与论文表 4 的 +2.8/+2.7/+1.9 同量级，非对称蒸馏的贡献被独立确认；若差距明显缩小，说明论文的优势部分来自其内部 40 万条高质量视频与特定教师，而非机制本身。</li><li><strong>一周内的额外一项</strong>（直接检验 §9）：再加一条支线 (C)，把 DMD 损失改到<strong>自回归 rollout 出来的样本</strong>上（哪怕只 rollout 2 个 chunk、并对更早的 chunk 截断梯度）。若 (C) 明显优于 (A)，就在小规模上复现了 Self Forcing 的核心结论，也就直接量化了本文最脆弱假设的代价。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>反例：4 步学生在三项指标上全面超过 100 步双向教师，更可能是反向 KL 的锐化效应命中了指标偏好，而不是学生真的更好。</strong></p><p>先看这个事实有多反常：表 4 里最终学生 94.7/64.4/30.1，多步双向教师 94.6/62.7/29.6。学生用 4 次前向、教师用 100 次前向，而学生的知识<strong>全部来自</strong>教师。信息论上学生不可能比教师包含更多关于数据分布的信息。那么它凭什么在三项上都更高？</p><p>替代解释是完整的。DMD 最小化的是反向 KL <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">KL</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">∥</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">data</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，这是寻峰的：学生被强烈惩罚&quot;跑到数据没有支撑的地方&quot;，但完全不被惩罚&quot;漏掉数据的某些模式&quot;。结果是学生把概率质量收缩到高密度区域——具体表现就是更干净、更锐、伪影更少的帧。而 VBench 的 Frame Quality 主要由美学与成像质量类指标构成，<strong>正是奖励锐利干净的</strong>。Text Alignment 同理：收缩到&quot;最典型的那种符合 prompt 的画面&quot;会提高 CLIP 类对齐分。</p><p>论文自己提供了这个解释的两处直接证据。第一，讨论里写明&quot;学生在逐帧画质上改进了双向教师，但在<strong>时序闪烁与输出多样性</strong>上更差&quot;。第二，Limitation 里承认 DMD 带来的多样性下降是&quot;反向 KL 类分布匹配方法的固有特性&quot;，并建议后续尝试 EM-Distillation、Score Implicit Matching 等更保多样性的目标。</p><p><strong>设计的判别实验</strong>：在同一组 prompt 上，为学生与教师各生成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 个种子的样本，测三件事：(i) <strong>召回率</strong>（recall / coverage），用 Precision-Recall for Generative Models 或改进版 density-coverage 在视频特征空间上算——寻峰会让 precision 高而 recall 低；(ii) 逐 prompt 的<strong>样本间多样性</strong>（成对特征距离均值）；(iii) 一个<strong>罕见模式命中率</strong>：构造一批需要非典型构图或非典型运动的 prompt（&quot;镜头从水下穿出水面&quot;&quot;物体在无重力下缓慢自旋&quot;），统计生成结果落在正确模式里的比例。</p><ul><li>若学生在 precision 上高、recall 上显著低于教师，且罕见模式命中率下降，那么&quot;学生超过教师&quot;应当被重新表述为&quot;学生在一组奖励锐利与典型性的指标上超过教师&quot;，而 VBench-Long 84.27 的第一名成绩需要配上多样性注脚。</li><li>若学生的 recall 与教师相当，寻峰解释被排除，那么本文的结论比它自己声称的还要强——少步蒸馏确实带来了净收益。</li></ul><p>一个更便宜的负对照：把教师的采样加大 CFG 尺度（人为制造寻峰效果）到与学生相近的锐度，再算三项指标。如果教师的分数因此追平甚至反超学生，那么差距的主体就被定位成了&quot;锐化&quot;而非&quot;蒸馏&quot;。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：本文的因果学生只有一个固定的时间粒度——chunk = 5 个 latent 帧、每 chunk 恒定 4 步去噪。这个粒度同时被三个互不相干的约束绑死：VAE 必须凑齐 5 个 latent 帧才能解码（作者在 Limitation 里明说延迟&quot;受限于当前 VAE 设计&quot;）；块因果掩码按 chunk 划分；DMD 的时间步采样也按 chunk 组织。于是&quot;每一段视频需要多少计算&quot;这件事完全无法自适应——一个静止镜头和一个剧烈运动的镜头花的算力一模一样。同时，误差累积的处理是<strong>被动的</strong>：靠教师没见过 rollout 来间接缓解，模型自身没有任何&quot;我这一步生成得好不好&quot;的信号。</p><p><strong>(b) 可借鉴的相邻领域工具</strong>：语音与语言生成里的<strong>推测解码（speculative decoding）与草稿-验证框架</strong>。核心思想是：用一个便宜的草稿模型快速往前跑若干步，再用一个昂贵但可信的验证器一次性检查这些步是否可接受，不可接受就回退重采。把它搬到视频自回归上，新的 framing 是：<strong>把误差累积当成一个可检测、可回退的事件，而不是一个只能靠训练分布来预防的隐患</strong>。这里的验证器有一个视频领域特有的、语言领域没有的天然候选——<strong>那个双向教师本身</strong>。教师虽然慢，但它对&quot;这段已经生成的视频是否落在数据分布上&quot;能给出可信的分数（这正是 DMD 里 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">real</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 做的事），而且验证一段视频比生成一段视频便宜得多（一次前向 vs 50 次）。</p><p><strong>(c) 第一个实验</strong>：不需要重训任何模型。取已训好的 CausVid 学生与它的双向教师，做一个纯推理时的闭环：学生自回归生成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个 chunk（草稿），把这 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个 chunk 加噪到某个固定时间步 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6887em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span></span></span></span>，用教师算一次分数并得到一个标量的&quot;分布外程度&quot;；若超过阈值，就丢弃这 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个 chunk 并用不同噪声重采（或让教师做一步修正后再交回学生续写）。先在 30 秒与 5 分钟两个长度上跑，测量：(i) 画质随帧数的衰减曲线相对无验证基线的改善；(ii) 平均每秒视频的额外教师调用次数与由此增加的端到端延迟；(iii) 回退触发的时间分布——它是否与图 8 里画质开始下滑的位置对齐。</p><p>这个实验的价值在于它同时检验两件事。如果回退触发的时刻与画质下滑高度对齐，就说明<strong>教师分数是误差累积的有效在线探测器</strong>，这本身是一个此前未被利用的信号，可以直接反哺训练（把它变成一个 rollout 期的辅助损失）。如果触发位置随机、与画质无关，那说明误差累积在分数空间里不可见，那么 Self Forcing 那条&quot;必须在训练时就 rollout&quot;的路线就是唯一解——这同样是一个干净、有信息量的结论。</p>',73)])])}const d=a(l,[["render",e]]);export{h as __pageData,d as default};
